def p = params instanceof Map ? params : [:]
def token = p.token
if (token == null || token.toString().trim() == '') {
    def tokenResp = runRequest.runRequest('feishu_tenant_token', [:])
    def tokenBody = new groovy.json.JsonSlurper().parseText(tokenResp.body.toString())
    token = tokenBody.tenant_access_token
}
def children = p.children
if (children != null && !(children instanceof String)) {
    children = groovy.json.JsonOutput.toJson(children)
}
def index = (p.index != null) ? p.index : -1
if (children == null || children.toString().trim() == '') {
    return [success: false, message: 'children 不能为空']
}
def resp = runRequest.runRequest('feishu_docx_create_blocks', [
    token: token,
    document_id: p.document_id,
    block_id: (p.block_id != null && p.block_id.toString().trim() != '') ? p.block_id : 'doc_root',
    index: index,
    children: children.toString()
])
return resp
